      "evidence": "The Boreal team holds planning on Thursdays."
    }
  ],
  "entity_aliases": [
    {
      "name": "Boreal team",
      "canonical": "Team Boreal",
      "evidence": "The Boreal team holds planning on Thursdays."
    }
  ]
}

